// 13 SPP (dont le capitaine) et 37 SPV : effectif total de 50.
export function volunteerPool(s){s.volunteerPool??=Array.from({length:37},(_,i)=>({id:14+i,tier:i<10?1:2,travel:4+i%8,worker:i%10<7,canLeaveWork:i%4===0,eveningBusy:i%7===0}));s.recallRequests??=[];return s.volunteerPool;}
export function volunteerActivity(p,minute){const h=minute/60%24;return p.worker&&h>=8&&h<18?'work':h>=10&&h<20&&p.id%5===0?'city':'home';}
export function availability(p,minute){const h=minute/60%24;if(p.worker&&!p.canLeaveWork&&h>=8&&h<18)return 'Au travail';if(p.eveningBusy&&h>=18&&h<21)return 'Obligation personnelle';return null;}
function present(s,p){return s.roster.some(r=>r.id===p.id&&r.present);}
function pending(s,p){return s.recallRequests.some(r=>r.personId===p.id&&r.status==='enroute')||s.volunteerReturning?.includes(p.id);}
export function recallCapacity(s){return volunteerPool(s).filter(p=>!present(s,p)&&!pending(s,p)&&!availability(p,s.minute)).length;}
export function requestVolunteers(s,level,rnd=Math.random){if(s.ended||![1,2,3].includes(Number(level)))return 0;level=Number(level)===1?1:2;const pool=volunteerPool(s),candidates=pool.filter(p=>(level===2||p.tier===1)&&!present(s,p)&&!pending(s,p));if(!candidates.length)return 0;const batch={id:(s.recallSerial=(s.recallSerial||0)+1),level,at:s.minute,called:candidates.length,unavailable:0};s.recallBatches??=[];s.recallBatches.push(batch);let n=0;for(const p of candidates){if(availability(p,s.minute)){batch.unavailable++;continue;}const night=s.minute/60%24<7||s.minute/60%24>=22;const preparation=(night?3:1)+rnd()*2;s.recallRequests.push({id:p.id+'-'+batch.id,personId:p.id,batch:batch.id,requestedAt:s.minute,activity:volunteerActivity(p,s.minute),preparation,at:s.minute+p.travel+preparation,status:'enroute',phase:'preparing'});n++;}return n;}
export function tickVolunteers(s,emit,arrivalReady=r=>s.minute>=r.at){for(const r of s.recallRequests||[]){if(r.status!=='enroute'||!arrivalReady(r))continue;let p=s.roster.find(p=>p.id===r.personId);const slot=Array.from({length:50},(_,i)=>i).find(i=>!s.roster.some(p=>p.present&&p.slot===i));if(slot==null)continue;if(!p){p={id:r.personId,kind:'SPV',engine:null};s.roster.push(p);}Object.assign(p,{present:true,slot});r.status='arrived';r.phase='available';s.freeStaff=s.roster.filter(p=>p.present&&!p.engine&&!['captain','nurse'].includes(p.role)).length;s.spv=true;emit(`SPV arrivé au CIS · rappel ${r.batch}.`);}}
export function cancelVolunteer(s,id){for(const r of s.recallRequests||[])if(r.batch===Number(id)&&r.status==='enroute')r.status='cancelled';}
const levelName=l=>l===1?'Équipe d’astreinte':'Appel général';
const mobilizable=(s,level)=>volunteerPool(s).filter(p=>(level===2||p.tier===1)&&!present(s,p)&&!pending(s,p)&&!availability(p,s.minute)).length;
export function volunteerPanel(s){volunteerPool(s);return `<section class="recallCompact"><div class="profileHeading"><h2>Renforts SPV</h2><button data-close aria-label="Fermer les renforts">×</button></div><div class="recallChoices">${[1,2].map(level=>`<button data-recall-level="${level}" ${s.ended||!mobilizable(s,level)?'disabled':''}><b>${levelName(level)}</b><span>${mobilizable(s,level)} mobilisables</span></button>`).join('')}</div><div id="recallStatus">${volunteerStatus(s)}</div><small class="recallNote">50 personnels au total · disponibilité selon l’heure.</small></section>`;}
export function volunteerStatus(s){
 const people=s.roster.filter(p=>p.present&&p.kind==='SPV'),waiting=(s.recallRequests||[]).filter(r=>r.status==='enroute'),eta=waiting.map(r=>Math.max(1,Math.round((r.at-s.minute)*60/s.speed))),min=eta.length?Math.min(...eta):0,max=eta.length?Math.max(...eta):0;
 return `<div class="recallNumbers"><span><b>${people.filter(p=>!p.engine).length}</b>Au CIS</span><span><b>${people.filter(p=>p.engine).length}</b>Engagés</span><span><b>${waiting.length}</b>En approche</span></div>${waiting.length?`<p class="recallEta">◷ Arrivées ≈ ${min===max?min:min+'–'+max} s</p><div class="recallTravel"><span>${waiting.filter(r=>r.phase==='preparing').length} préparation</span><span>${waiting.filter(r=>['driving','parking'].includes(r.phase)).length} trajet</span><span>${waiting.filter(r=>['walking','changing'].includes(r.phase)).length} vestiaires</span></div>`:'<p class="recallEta">Aucun renfort en route.</p>'}${(s.recallBatches||[]).filter(b=>waiting.some(r=>r.batch===b.id)).map(b=>`<div class="recallBatch compactBatch"><span>${levelName(b.level)}<small>${waiting.filter(r=>r.batch===b.id).length} attendus</small></span><button data-cancel-recall="${b.id}" title="Annuler les arrivées restantes" aria-label="Annuler ${levelName(b.level).toLowerCase()}">×</button></div>`).join('')}`;
}
export function initObjectives(c,minute,travelMinutes=20){c.objectiveStart=minute;c.arrivalBudget=Math.ceil((12+travelMinutes*1.5)/5)*5;c.finishBudget=c.arrivalBudget+Math.ceil(c.duration*1.5)+20;}
export function objectiveResult(c){return {arrival:c.firstUsefulArrival!=null?c.firstUsefulArrival-c.objectiveStart<=c.arrivalBudget:null,finish:(c.siteCompletedAt??c.closedAt)!=null?(c.siteCompletedAt??c.closedAt)-c.objectiveStart<=c.finishBudget:null};}
export function objectivesPanel(c,minute,speed=60){const result=objectiveResult(c),chip=(label,budget,done,ok)=>{const remaining=Math.ceil(c.objectiveStart+budget-minute),seconds=Math.max(0,Math.round(remaining*60/speed)),real=seconds>=60?Math.floor(seconds/60)+' min '+seconds%60+' s':seconds+' s';return `<span class="objectiveChip ${done!=null?(ok?'objectiveGood':'objectiveLate'):remaining<0?'objectiveLate':''}" title="${label} : objectif ${budget} minutes de garde depuis l’appel. À cette vitesse : ${real} réelles restantes.">${done!=null?(ok?'✓':'⚠'):'◷'} ${label} <b>${done!=null?Math.round(done-c.objectiveStart)+' min':remaining>=0?real+' restantes':'Délai dépassé'}</b></span>`;};return `<section class="objectives compactObjectives" aria-label="Objectifs de mission">${chip('Arrivée',c.arrivalBudget,c.firstUsefulArrival,result.arrival)}${chip('Sur place',c.finishBudget,c.siteCompletedAt??c.closedAt,result.finish)}</section>`;}
